/* Merge:
   x ≡ r1 (mod m1)
   x ≡ r2 (mod m2)
   into
   x ≡ r (mod lcm)
   return 1 if possible, 0 if inconsistent
*/
static int crt_merge(ll r1, ll m1, ll r2, ll m2, ll *r, ll *m) {
    ll x, y;
    ll g = exgcd(m1, m2, &x, &y);
    ll diff = r2 - r1;
    if (diff % g != 0) return 0;

    ll mod = m2 / g;

    __int128 t = (__int128)(diff / g) * x;
    ll k = (ll)(t % mod);
    if (k < 0) k += mod;

    __int128 nr = (__int128)r1 + (__int128)m1 * k;
    ll lcm = m1 / g * m2;
    ll rr = (ll)(nr % lcm);
    if (rr < 0) rr += lcm;

    *r = rr;
    *m = lcm;
    return 1;
}

