using i128 = __int128_t;

static int64 exgcd(int64 a, int64 b, int64 &x, int64 &y) {
    if (b == 0) {
        x = 1; y = 0;
        return a;
    }
    int64 x1, y1;
    int64 g = exgcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

static int64 mod_mul(int64 a, int64 b, int64 mod) {
    return (int64)((i128)a * b % mod);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    // We solve the system:
    // x ≡ a_i (mod m_i), where m_i = i+1 for i=1..n  => moduli 2..n+1
    //
    // Since the number of chopsticks is odd, additionally:
    // x ≡ 1 (mod 2)
    //
    // We merge all congruences with generalized CRT.
    //
    // If inconsistent -> -1.
    // Otherwise all solutions are x ≡ r (mod lcm of moduli).
    // The maximum possible final-day number less than or equal to n+1? No upper bound
    // is given by the statement as presented, so the intended answer is the unique
    // representative modulo lcm in [0, lcm). However, because "maximum possible"
    // in the classic chopsticks setting means among candidates within the holder size,
    // the standard interpretation is to output the largest valid x in [0, lcm).
    //
    // Thus we output r normalized to [0, lcm), or -1 if impossible.

    int64 r = 1;   // odd
    int64 mod = 2;

    for (int i = 1; i <= n; ++i) {
        int64 a;
        cin >> a;
        int64 m = i + 1;

        a %= m;
        if (a < 0) a += m;

        int64 x, y;
        int64 g = exgcd(mod, m, x, y);

        if ((a - r) % g != 0) {
            cout << -1 << '\n';
            return 0;
        }

        int64 m2 = m / g;
        int64 diff = (a - r) / g;

        int64 inv = x % m2;
        if (inv < 0) inv += m2;

        int64 t = mod_mul((diff % m2 + m2) % m2, inv, m2);

        i128 new_r = (i128)r + (i128)mod * t;
        i128 new_mod = (i128)mod / g * m;

        r = (int64)(new_r % new_mod);
        if (r < 0) r += (int64)new_mod;
        mod = (int64)new_mod;
    }

    cout << r << '\n';
    return 0;
}

