import java.util.*;

public class Main {
    static long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }

    static long[] extgcd(long a, long b) {
        if (b == 0) return new long[]{a, 1, 0};
        long[] r = extgcd(b, a % b);
        return new long[]{r[0], r[2], r[1] - (a/b)*r[2]};
    }

    // Combine: x ≡ r1 (mod m1) and x ≡ r2 (mod m2)
    // Returns {r, m} or null if inconsistent
    static long[] combine(long r1, long m1, long r2, long m2) {
        long g = gcd(m1, m2);
        if ((r2 - r1) % g != 0) return null;
        long lcm = m1 / g * m2;
        long[] eg = extgcd(m1/g, m2/g);
        long x = eg[1];
        long diff = (r2 - r1) / g;
        long mod = m2 / g;
        long t = (diff % mod * (x % mod) % mod + mod) % mod;
        long r = r1 + m1 * t;
        r = ((r % lcm) + lcm) % lcm;
        return new long[]{r, lcm};
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long curR = 0, curM = 1;
        boolean inconsistent = false;
        while (sc.hasNextLong()) {
            long m = sc.nextLong();
            if (!sc.hasNextLong()) break;
            long r = sc.nextLong();
            if (inconsistent) continue;
            long[] res = combine(curR, curM, r, m);
            if (res == null) { inconsistent = true; }
            else { curR = res[0]; curM = res[1]; }
        }
        if (inconsistent) System.out.println(-1);
        else System.out.println(curR);
    }
}

