public class Main {
    // Extended GCD: returns {g, x, y} such that ax + by = g = gcd(a,b)
    static long[] egcd(long a, long b) {
        if (b == 0) return new long[]{a, 1, 0};
        long[] t = egcd(b, a % b);
        long g = t[0], x = t[2], y = t[1] - (a / b) * t[2];
        return new long[]{g, x, y};
    }

    // Safe lcm check against limit
    static long lcmLimited(long a, long b, long limit) {
        long g = gcd(a, b);
        a /= g;
        if (a > limit / b) return limit + 1;
        return a * b;
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return Math.abs(a);
    }

    // Merge:
    // x ≡ r1 (mod m1)
    // x ≡ r2 (mod m2)
    // returns {r, m} with 0 <= r < m, or null if inconsistent
    static long[] crtMerge(long r1, long m1, long r2, long m2) {
        long g = gcd(m1, m2);
        long diff = r2 - r1;
        if (diff % g != 0) return null;

        long m1g = m1 / g;
        long m2g = m2 / g;

        long[] eg = egcd(m1g, m2g); // eg[1] is inverse of m1g mod m2g
        long inv = eg[1];

        long tMod = m2g;
        long t = diff / g;

        long k = modMul(modNormalize(t, tMod), modNormalize(inv, tMod), tMod);
        long lcm = m1 * m2g;

        long r = r1 + m1 * k;
        r = modNormalize(r, lcm);
        return new long[]{r, lcm};
    }

    static long modNormalize(long x, long mod) {
        long r = x % mod;
        if (r < 0) r += mod;
        return r;
    }

    static long modMul(long a, long b, long mod) {
        // mod is small enough for long here, but use repeated doubling to stay safe
        long res = 0;
        while (b > 0) {
            if ((b & 1) == 1) {
                res = (res + a) % mod;
            }
            a = (a << 1) % mod;
            b >>= 1;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n;
        long m;
        try {
            n = fs.nextInt();
            m = fs.nextLong();
        } catch (Exception e) {
            return;
        }

        long r = 0;   // current remainder
        long mod = 1; // current modulus

        for (int i = 1; i <= n; i++) {
            long ai = fs.nextLong(); // recorded remainder modulo i
            long mi = i;

            ai = modNormalize(ai, mi);

            long[] merged = crtMerge(r, mod, ai, mi);
            if (merged == null) {
                System.out.println(-1);
                return;
            }
            r = merged[0];
            mod = merged[1];
        }

        // Need maximum x <= m such that x ≡ r (mod mod)
        if (r > m) {
            System.out.println(-1);
            return;
        }

        long ans = r + ((m - r) / mod) * mod;
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) throw new EOFException();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
